    H, W = len(grid), len(grid[0])
    pairs = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == fg_value:
                if c + 1 < W and grid[r][c+1] == fg_value:
                    pairs.add((r,c))
                    pairs.add((r,c+1))
