# I think the rule is about COMPONENTS:
# - If a component touches ROW 0 → all cells in that component become 2
# - If a component touches LEFT EDGE (col 0) → all cells become 2
# - Otherwise → 1

def apply_component_rule(grid, fg, bg=None):
    bg = grid[0][0] if bg is None else bg
    H, W = len(grid), len(grid[0])
    visited = [[False]*W for _ in range(H)]
    output = [[bg]*W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] != fg or visited[r][c]:
                continue
            # Find component
            comp = []
            q = [(r,c)]
            visited[r][c] = True
            while q:
                cr, cc = q.pop(0)
                comp.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if grid[nr][nc] == fg and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))

            # Check if component touches row 0 or col 0
            touches_row0 = any(cr == 0 for cr, cc in comp)
            touches_col0 = any(cc == 0 for cr, cc in comp)

            if touches_row0 or touches_col0:
                # All cells in component become 2
                for cr, cc in comp:
                    output[cr][cc] = 2
            else:
                # All cells in component stay 1
                for cr, cc in comp:
                    output[cr][cc] = 1

    return output

